def app(label,command):
    args=[sys.executable,'-B',str(root/'app/librarian.py'),'review-loop',command,'--fixture-root',str(book),'--request','request.json']
    if command=='record':args+=['--decision','decision.json']
    p=subprocess.run(args,cwd=str(root),capture_output=True,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1'),timeout=90)
    (evidence/(label+'.stdout')).write_bytes(p.stdout);(evidence/(label+'.stderr')).write_bytes(p.stderr);dump(evidence/(label+'.command.json'),{'argv':args,'exit':p.returncode})
    assert p.returncode==0,(label,p.stdout.decode(errors='replace')[:600],p.stderr.decode(errors='replace')[:600]);return json.loads(p.stdout)
